13	export function BundleSelector() {
14	  const { bundle, setBundle, purchaseType } = useCart();
15	  const base =
16	    purchaseType === "subscribe"
17	      ? VELA_PRODUCT.priceSubscribe
18	      : VELA_PRODUCT.priceOnetime;
19	
