27	          const perBottle = (base * VELA_PRODUCT.bundleMultipliers[opt.size]) / opt.size;
28	          const savings = VELA_PRODUCT.bundleSavings[opt.size];
29	          const active = bundle === opt.size;
30	          return (
31	            <button
32	              key={opt.size}
33	              type="button"
34	              onClick={() => setBundle(opt.size)}
35	              className={cn(
