37	                active
38	                  ? "border-forest-800 bg-cream-100 -translate-y-0.5"
39	                  : "border-cream-300 bg-cream-50 hover:border-forest-400",
40	              )}
41	              aria-pressed={active}
42	            >
43	              {opt.popular && (
44	                <Badge
45	                  variant="secondary"
46	                  className="absolute -top-2 right-2 bg-amber-500 text-forest-950 hover:bg-amber-500"
47	                >
48	                  Most popular
49	                </Badge>
50	              )}
51	              <span className="text-sm font-semibold text-forest-950">{opt.label}</span>
52	              <span className="font-mono text-xs text-ink-600">
53	                ${perBottle.toFixed(2)}/bottle
54	              </span>
55	              {savings > 0 ? (
56	                <span className="font-mono text-xs text-forest-700">
57	                  Save {savings}%
58	                </span>
59	              ) : (
60	                <span className="font-mono text-xs text-ink-400">—</span>
61	              )}
62	            </button>
63	          );
64	        })}
65	      </div>
66	    </div>
67	  );
