1	import { Dialog, DialogContent, DialogTitle } from "@/components/ui/dialog";
2	import { Button } from "@/components/ui/button";
3	import { useEffect, useState } from "react";
4	import { useCart } from "@/components/shared/cart-context";
5	import { FlaskConical } from "lucide-react";
6	
7	const SESSION_KEY = "vela-exit-intent-shown";
8	
9	export function ExitIntent() {
10	  const { cartOpen } = useCart();
11	  const [open, setOpen] = useState(false);
12	
13	  useEffect(() => {
14	    if (typeof window === "undefined") return;
15	    if (window.matchMedia("(max-width: 768px)").matches) return;
16	    if (sessionStorage.getItem(SESSION_KEY)) return;
17	
18	    const handler = (e: MouseEvent) => {
19	      if (e.clientY <= 0 && !cartOpen) {
20	        setOpen(true);
21	        sessionStorage.setItem(SESSION_KEY, "1");
22	        document.removeEventListener("mouseleave", handler);
23	      }
24	    };
25	    document.addEventListener("mouseleave", handler);
26	    return () => document.removeEventListener("mouseleave", handler);
27	  }, [cartOpen]);
28	
29	  return (
30	    <Dialog open={open} onOpenChange={setOpen}>
31	      <DialogContent className="max-w-md border-cream-300 bg-cream-50 sm:max-w-md">
32	        <div className="flex flex-col items-center text-center">
33	          <div className="mb-4 flex size-12 items-center justify-center rounded-full bg-amber-100 text-amber-800">
34	            <FlaskConical className="size-6" />
35	          </div>
36	          <DialogTitle className="font-display text-2xl font-semibold tracking-tight text-forest-950">
37	            One more thing.
38	          </DialogTitle>
39	          <p className="mt-2 text-sm leading-relaxed text-ink-700">
40	            See the full ingredient label before you decide. Every active. Every dose. Every excipient.
41	          </p>
42	          <div className="mt-6 flex w-full flex-col gap-2">
43	            <Button
44	              onClick={() => {
45	                setOpen(false);
46	                document.getElementById("ingredients")?.scrollIntoView({ behavior: "smooth" });
47	              }}
48	              className="w-full bg-forest-800 text-cream-50 hover:bg-forest-900"
49	            >
50	              View label
51	            </Button>
52	            <Button
53	              variant="ghost"
54	              onClick={() => setOpen(false)}
55	              className="text-xs text-ink-500 hover:text-ink-700"
56	            >
57	              No thanks
58	            </Button>
59	          </div>
60	        </div>
61	      </DialogContent>
62	    </Dialog>
63	  );
64	}
