1	import { useCallback, useMemo, useState } from "react";
2	import type { CartState, CartActions, BundleSize, PurchaseType } from "@/lib/types";
3	import { VELA_PRODUCT, calcUnitPrice, calcTotalPrice } from "@/data/mock";
4	
5	export function useCartState(): CartState & CartActions {
6	  const [purchaseType, setPurchaseType] = useState<PurchaseType>("subscribe");
7	  const [bundle, setBundle] = useState<BundleSize>(1);
8	  const [cartOpen, setCartOpen] = useState<boolean>(false);
9	
10	  const unitPrice = useMemo(
11	    () => calcUnitPrice(VELA_PRODUCT, purchaseType, bundle),
12	    [purchaseType, bundle],
13	  );
14	  const totalPrice = useMemo(
15	    () => calcTotalPrice(VELA_PRODUCT, purchaseType, bundle),
16	    [purchaseType, bundle],
17	  );
18	
19	  const openCart = useCallback(() => setCartOpen(true), []);
20	  const closeCart = useCallback(() => setCartOpen(false), []);
21	  const toggleCart = useCallback(() => setCartOpen((v) => !v), []);
22	
23	  return {
24	    purchaseType,
25	    bundle,
26	    cartOpen,
27	    unitPrice,
28	    totalPrice,
29	    setPurchaseType,
30	    setBundle,
31	    openCart,
32	    closeCart,
33	    toggleCart,
34	  };
35	}
