    { path: '/', Component: Index, text: /one brand\. five conversion/i },
    { path: '/variant-1', Component: Variant1Spec, text: /five actives/i },
    { path: '/variant-2', Component: Variant2Lifestyle, text: /think clearly/i },
    { path: '/variant-3', Component: Variant3Spec, text: /no proprietary blends/i },
