// --- Test 6: ExitIntent suppressed on mobile ---
// Hypothesis: with matchMedia max-width:768px returning true, mouseleave does NOT open the dialog
it('ExitIntent: dialog does not open on mobile viewport', async () => {
  // Mock matchMedia to simulate mobile
  const mockMatchMedia = (query: string) => ({
    matches: query === '(max-width: 768px)',
    media: query,
    onchange: null,
    addListener: vi.fn(),
    removeListener: vi.fn(),
    addEventListener: vi.fn(),
    removeEventListener: vi.fn(),
